package io.github.jasper.monitoring.api.management.model;
public final class WhitelistView { private final String id,systemScope; private WhitelistView(String id,String scope){this.id=id;this.systemScope=scope;} public static WhitelistView of(String id,String scope){if(id==null||id.trim().isEmpty()||scope==null||scope.trim().isEmpty())throw new IllegalArgumentException("invalid whitelist view");return new WhitelistView(id,scope);} public String getId(){return id;} public String getSystemScope(){return systemScope;} }
